home:','info','0','','',NULL,'',0,'',NULL,21,0,0,0,0,0,0,'',NULL,0,'',0,'',0,'C&ocirc;ng ty TNHH C&ocirc;ng nghệ Vật liệu mới B&aacute;ch Mỹ Nam Kinh được th&agrave; nh lập năm 2002 tại quận Cao Thuần, th&agrave;nh phố Nam Kinh. T&ecirc;n cũ của c&ocirc;ng ty l&agrave; &ldquo;C&ocirc;ng ty TNHH Titan Tương B ảo Nam Kinh&rdquo; v&agrave; &ldquo;C&ocirc;ng ty TNHH Nhựa B&aacute;ch Mỹ Nam Kinh&rdquo;. Hiện nay, c&ocirc;ng ty c&oacute; 4 chi nh&aacute;nh gồm: Chi nh&aacute;nh Quảng T&acirc;y, Chi nh&aacute;nh Quảng Đ&ocirc;ng, Chi nh&aacute;nh Thường Ch&acirc;u v&agrave; Chi nh&aacute;nh Thượng Hải, c&ugrave;ng với nhiều sản phẩm đa dạng.<br />\r\n<br />\r\nTrải qua 20 năm kh&ocirc;ng ngừng học hỏi v&agrave; ph&aacute;t triển, hiện tại t rụ sở ch&iacute;nh Nam Kinh c&oacute; 9 d&acirc;y chuyền sản xuất nhựa Amin, 4 d&acirc;y chuyền sản xuất chất ổn định Canxi-Kẽm tổng hợp....','',1780387701),(16,'Sản phẩm nổi bật','Sản phẩm nổi bật','Sản phẩm nổi bật',0,13,1,'','','','','san-pham-noi-bat/','',':hothome:','product','0','','',NULL,'',0,'',NULL,21,0,0,0,0,0,0,'',NULL,0,'',0,'',0,'','',1780389794),(18,'Chất ổn định','Chất ổn định','Chất ổn định',9,15,1,'','','','','chat-on-dinh/','',':','product','0','','',NULL,'',0,'',NULL,21,0,0,0,0,0,0,'',NULL,0,'/uploaded/san-pham/it-dt.png',0,'',0,'','',1781598571),(19,'Chất ổn định dạng lỏng','Chất ổn định dạng lỏng','Chất ổn định dạng lỏng',9,16,1,'','','','','chat-on-dinh-dang-long/','',':','product','0','','',NULL,'',0,'',NULL,21,0,0,0,0,0,0,'',NULL,0,'/uploaded/san-pham/item1.png',0,'',0,'','',1781065412),(20,'SÁP PE','SÁP PE','SÁP PE',9,17,1,'','','','','sap-pe/','',':','product','0','','',NULL,'',0,'',NULL,21,0,0,0,0,0,0,'',NULL,0,'/uploaded/san-pham/item3.png',0,'',0,'','',1781065567),(21,'SÁP PP','SÁP PP','SÁP PP',9,18,1,'','','','','sap-pp/','',':','product','0','','',NULL,'',0,'',NULL,21,0,0,0,0,0,0,'',NULL,0,'/uploaded/san-pham/item4.png',0,'',0,'','',1781065570),(22,'Barium Sulfate','Barium Sulfate','Barium Sulfate',9,19,1