INSERT INTO `product` VALUES (1,16,'PVC Leather Series','/uploaded/san-pham/f93045dc62665ee52f9a7e07bf4c7af409dd26dd.png','',0,'',0,NULL,'Được sản xuất th&ocirc;ng qua quy tr&igrave;nh tổng hợp cải tiến sử dụng axit stearic chất lượng cao v&agrave; thể hiện c&aacute;c đặc t&iacute;nh sau: Khả năng b&ocirc;i trơn, ph&acirc;n t&aacute;n tốt, khả năng chống thấm nước tuyệt vời, độ trong suốt v&agrave; ổn định thời tiết tốt, kh&ocirc;ng độc hại, kh&ocirc;ng nhuộm m&agrave;u sunfua, &iacute;t h&igrave;nh th&agrave;nh m&agrave;u ban đầu','',1780392060,1,8,1,0,1,'',':0:','',0,'PVC Leather Series','','','','','','',NULL,'','pvc-leather-series.html',NULL,NULL,NULL,_binary '0,0','0','{\"45\":\"\",\"43\":\"\",\"46\":\"\"}','','',NULL,'<p><strong>T&ecirc;n h&oacute;a chất</strong>: ZINC STEARATE</p>\r\n\r\n<p><strong>M&atilde; sản phẩm</strong>: ZTLC ( 145 &hellip;161 )</p>\r\n\r\n<p><strong>C&ocirc;ng thức h&oacute;a học</strong>: Zn(C17H35COO)2</p>\r\n\r\n<p><strong>Cas No</strong>: 558-05-1</p>\r\n\r\n<h2>M&ocirc; tả sản phẩm:</h2>\r\n\r\n<p><strong>ZTLC ( 145,148,155,160,161 ):&nbsp;</strong>Được sản xuất th&ocirc;ng qua quy tr&igrave;nh tổng hợp cải tiến sử dụng axit stearic chất lượng cao v&agrave; thể hiện c&aacute;c đặc t&iacute;nh sau: Khả năng b&ocirc;i trơn, ph&acirc;n t&aacute;n tốt, khả năng chống thấm nước tuyệt vời, độ trong suốt v&agrave; ổn định thời tiết tốt, kh&ocirc;ng độc hại, kh&ocirc;ng nhuộm m&agrave;u sunfua, &iacute;t h&igrave;nh th&agrave;nh m&agrave;u ban đầu<br />\r\n<br />\r\n<img alt=\"\" src=\"/uploaded/san-pham/thong-so.jpg\" style=\"width: 100%;\" /> Đ&oacute;ng bao: 20kg/bao<br />\r\n<br />\r\nĐộ ổn định lưu trữ: 2 năm trong điều kiện bảo quản kh&ocirc; r&aacute;o, tho&aacute;ng m&aacute;t trong bao b&igrave; gốc<br />\r\n&nbsp;</p>\r\n\r\n<h2>Ứng dụng:</h2>\r\n\r\n<ul>\r\n	<li>Tấm cao su v&agrave; EVA d&ugrave;ng l&agrave;m chất b&ocirc;i trơn, chất ph&acirc;n t&aacute;n b&ecirc;n trong v&agrave; để phủi bụi</li>\r\n	<li>D&ugrave;ng cho sơn, lớp phủ ho&aacute; chất, v để chống chảy tự do v&agrave; chống ẩm</li>\r\n	<li>Cho nhựa : EPS, PE, PP, PVC, hạt m&agrave;u Masterbach, Taical, Ống nhựa&hellip;.</li>\r\n	<li>Vật liệu Composite polymer đặc biệt.</li>\r\n</ul>\r\n','',NULL,'',0,'[{\"image_path\":\"\\/uploaded\\/san-pham\\/it-dt.png\",\"image_name\":\"\",\"image_desc\":\"\",\"image_thu_tu\":\"\"},{\"image_path\":\"\\/uploaded\\/san-pham\\/item3.png\",\"image_name\":\"\",\"image_desc\":\"\",\"image_thu_tu\":\"\"},{\"image_path\":\"\\/uploaded\\/san-pham\\/item2.png\",\"image_name\":\"\",\"image_desc\":\"\",\"image_thu_tu\":\"\"}]',1780392388,0),(2,16,'PVC Leather Series','/uploaded/san-pham/it-dt.png','',0,'',0,NULL,'Được sản xuất th&ocirc;ng qua quy tr&igrave;nh tổng hợp cải tiến sử dụng axit stearic chất lượng cao v&agrave; thể hiện c&aacute;c đặc t&iacute;nh sau: Khả năng b&ocirc;i trơn, ph&acirc;n t&aacute;n tốt, khả năng chống thấm nước tuyệt vời, độ trong suốt v&agrave; ổn định thời tiết tốt, kh&ocirc;ng độc hại, kh&ocirc;ng nhuộm m&agrave;u sunfua, &iacute;t h&igrave;nh th&agrave;nh m&agrave;u ban đầu','',1780392060,1,8,2,0,1,'',':','',0,'PVC Leather Series','','','','','','',NULL,'','pvc-leather-series.html',NULL,NULL,NULL,_binary '0,0','0','{\"45\":\"\",\"43\":\"\",\"46\":\"\"}','','',NULL,'<p><strong>T&ecirc;n h&oacute;a chất</strong>: ZINC STEARATE</p>\r\n\r\n<p><strong>M&atilde; sản phẩm</strong>: ZTLC ( 145 &hellip;161 )</p>\r\n\r\n<p><strong>C&ocirc;ng thức h&oacute;a học</strong>: Zn(C17H35COO)2</p>\r\n\r\n<p><strong>Cas No</strong>: 558-05-1</p>\r\n\r\n<h2>M&ocirc; tả sản phẩm:</h2>\r\n\r\n<p><strong>ZTLC ( 145,148,155,160,161 ):&nbsp;</strong>Được sản xuất th&ocirc;ng qua quy tr&igrave;nh tổng hợp cải tiến sử dụng axit stearic chất lượng cao v&agrave; thể hiện c&aacute;c đặc t&iacute;nh sau: Khả năng b&ocirc;i trơn, ph&acirc;n t&aacute;n tốt, khả năng chống thấm nước tuyệt vời, độ trong suốt v&agrave; ổn định thời tiết tốt, kh&ocirc;ng độc hại, kh&ocirc;ng nhuộm m&agrave;u sunfua, &iacu