 bach my nam kinh duoc tha nh lap nam 2002 tai quan cao thuan, thanh pho nam kinh. ten cu cua cong ty la “cong ty tnhh titan tuong b ao nam kinh” va “cong ty tnhh nhua bach my nam kinh”. hien nay, cong ty co 4 chi nhanh gom: chi nhanh quang tay, chi nhanh quang dong, chi nhanh thuong chau va chi nhanh thuong hai, cung voi nhieu san pham da dang.\r\n\r\ntrai qua 20 nam khong ngung hoc hoi va phat trien, hien tai t ru so chinh nam kinh co 9 day chuyen san xuat nhua amin, 4 day chuyen san xuat chat on dinh canxi-kem tong hop....','','',1780387640,NULL,'',1,'',NULL,'gioi-thieu-trang-chu/',NULL,'id_category',15,'category','/uploaded/gioi-thieu/gioithieu.jpg'),(14,'Diện tích sản xuất','dien tich san xuat','15.000m2+','15.000m2+','','',1780388068,NULL,NULL,1,'',NULL,'dien-tich-san-xuat.html',15,'id_info',1,'info','/uploaded/ico/Group%20605.png'),(15,'Công suất sản xuất','cong suat san xuat','1.500tấn+','1.500tan+','','',1780388130,NULL,NULL,1,'',NULL,'cong-suat-san-xuat.html',15,'id_info',2,'info','/uploaded/ico/industrial-2%201.png'),(16,'Khách hàng hài lòng','khach hang hai long','98%','98%','','',1780388142,NULL,NULL,1,'',NULL,'khach-hang-hai-long.html',15,'id_info',3,'info','/uploaded/ico/Group%20604.png'),(17,'Quốc gia xuất khẩu','quoc gia xuat khau','30+','30+','','',1780388152,NULL,NULL,1,'',NULL,'quoc-gia-xuat-khau.html',15,'id_info',4,'info','/uploaded/ico/Vector.png'),(18,'Sản phẩm nổi bật','san pham noi bat','','','','',1780389794,NULL,'',1,'',NULL,'san-pham-noi-bat/',NULL,'id_category',16,'category',''),(19,'Sản phẩm cung cấp','san pham cung cap','','','','',1780390026,NULL,'',1,'',NULL,'san-pham-cung-cap/',NULL,'id_category',17,'category',''),(20,'Chất ổn định','chat on dinh','','','','',1780390042,NULL,'',1,'',NULL,'chat-on-dinh/',NULL,'id_category',18,'category',''),(21,'Chất ổn định dạng lỏng','chat on dinh dang long','','','','',1780390115,NULL,'',1,'',NULL,'chat-on-dinh-dang-long/',NULL,'id_category',19,'category','/uploaded/san-pham/item1.png'),(22,'SÁP 